Here is the commit message:
scsi: Fix more error handling in SCSI_IOCTL_SEND_COMMAND

Fix an error path in SCSI_IOCTL_SEND_COMMAND that calls
blk_put_request(rq) on an invalid IS_ERR(rq) pointer.

Fixes: a492f075450f ("block,scsi: fixup blk_get_request dead queue scenarios")
Signed-off-by: Tony Battersby <tonyb@cybernetics.com>
Signed-off-by: Jens Axboe <axboe@fb.com>

Here is the root cause:
The bug was caused by the improper handling of the `rq` pointer in the `sg_scsi_ioctl` function. When the `blk_get_request` function returned an error (indicated by `IS_ERR(rq)` being true), the original code did not correctly manage the flow to ensure that `blk_put_request(rq)` was only called if `rq` was a valid pointer. This could lead to dereferencing an invalid pointer, resulting in undefined behavior or crashes.

Here is the patch:
 #define OMAX_SB_LEN 16          /* For backward compatibility */
 int sg_scsi_ioctl(struct request_queue *q, struct gendisk *disk, fmode_t mode,
 		struct scsi_ioctl_command __user *sic)
 {
 	struct request *rq;
 	int err;
 	unsigned int in_len, out_len, bytes, opcode, cmdlen;
 	char *buffer = NULL, sense[SCSI_SENSE_BUFFERSIZE];

 	if (!sic)
 		return -EINVAL;

 	/*
 	 * get in an out lengths, verify they don't exceed a page worth of data
 	 */
 	if (get_user(in_len, &sic->inlen))
 		return -EFAULT;
 	if (get_user(out_len, &sic->outlen))
 		return -EFAULT;
 	if (in_len > PAGE_SIZE || out_len > PAGE_SIZE)
 		return -EINVAL;
 	if (get_user(opcode, sic->data))
 		return -EFAULT;

 	bytes = max(in_len, out_len);
 	if (bytes) {
 		buffer = kzalloc(bytes, q->bounce_gfp | GFP_USER| __GFP_NOWARN);
 		if (!buffer)
 			return -ENOMEM;

 	}

 	rq = blk_get_request(q, in_len ? WRITE : READ, __GFP_WAIT);
 	if (IS_ERR(rq)) {
 		err = PTR_ERR(rq);
-		goto error;
+		goto error_free_buffer;
 	}
 	blk_rq_set_block_pc(rq);

 	cmdlen = COMMAND_SIZE(opcode);

 	/*
 	 * get command and data to send to device, if any
 	 */
 	err = -EFAULT;
 	rq->cmd_len = cmdlen;
 	if (copy_from_user(rq->cmd, sic->data, cmdlen))
 		goto error;

 	if (in_len && copy_from_user(buffer, sic->data + cmdlen, in_len))
 		goto error;

 	err = blk_verify_command(rq->cmd, mode & FMODE_WRITE);
 	if (err)
 		goto error;

 	/* default.  possible overriden later */
 	rq->retries = 5;

 	switch (opcode) {
 	case SEND_DIAGNOSTIC:
 	case FORMAT_UNIT:
 		rq->timeout = FORMAT_UNIT_TIMEOUT;
 		rq->retries = 1;
 		break;
 	case START_STOP:
 		rq->timeout = START_STOP_TIMEOUT;
 		break;
 	case MOVE_MEDIUM:
 		rq->timeout = MOVE_MEDIUM_TIMEOUT;
 		break;
 	case READ_ELEMENT_STATUS:
 		rq->timeout = READ_ELEMENT_STATUS_TIMEOUT;
 		break;
 	case READ_DEFECT_DATA:
 		rq->timeout = READ_DEFECT_DATA_TIMEOUT;
 		rq->retries = 1;
 		break;
 	default:
 		rq->timeout = BLK_DEFAULT_SG_TIMEOUT;
 		break;
 	}

 	if (bytes && blk_rq_map_kern(q, rq, buffer, bytes, __GFP_WAIT)) {
 		err = DRIVER_ERROR << 24;
 		goto error;
 	}

 	memset(sense, 0, sizeof(sense));
 	rq->sense = sense;
 	rq->sense_len = 0;

 	blk_execute_rq(q, disk, rq, 0);

 	err = rq->errors & 0xff;	/* only 8 bit SCSI status */
 	if (err) {
 		if (rq->sense_len && rq->sense) {
 			bytes = (OMAX_SB_LEN > rq->sense_len) ?
 				rq->sense_len : OMAX_SB_LEN;
 			if (copy_to_user(sic->data, rq->sense, bytes))
 				err = -EFAULT;
 		}
 	} else {
 		if (copy_to_user(sic->data, buffer, out_len))
 			err = -EFAULT;
 	}

 error:
+	blk_put_request(rq);
+
+error_free_buffer:
 	kfree(buffer);
-	if (rq)
-		blk_put_request(rq);
+
 	return err;
 }
 EXPORT_SYMBOL_GPL(sg_scsi_ioctl);


